VALUES
	(1,1,1,'100 Template 1','A template for the 100 layout','<template>\n    <tr>\n        <td colspan=\"3\" align=\"left\" valign=\"top\" width=\"100%\" height=\"10\" style=\"border-collapse:collapse; mso-table-lspace: 0pt; mso-table-rspace: 0pt; mso-line-height-rule: exactly; line-height: 10px;\"><!--[if gte mso 15]>&nbsp;<![endif]--></td>\n    </tr>\n    <tr>\n        <td align=\"left\" valign=\"top\" width=\"10\"></td>\n        <td align=\"left\" valign=\"top\" width=\"580\" class=\"W300\">\n            <table border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"100%\">\n                <tr>\n                    <td align=\"left\" valign=\"top\" width=\"100%\">\n                        <!--Headline-->\n                        <table align=\"left\" class=\"W300\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"100%\">\n                            <tr>\n                                <td align=\"left\" valign=\"top\" width=\"100%\" style=\"font-family:Helvetica, Arial, sans-serif;color:{{ theme.font_color }};font-size:{{ fields.headline_font_size }};mso-line-height-rule:exactly;line-height:{{ fields.headline_font_size }};font-weight:bold;padding-bottom:10px;\"><!--[if mso]><a class=\"incomments font-color\" href=\"%%=RedirectTo(@bannerLink)=%%\" alias=\"Vacoda Text Banner\" style=\"text-decoration:none;\"><strong style=\"text-decoration:none;color:{{ theme.font_color }};\"><![endif]-->{{ fields.headline }}<!--[if mso]></strong></a><![endif]--></td>\n                            </tr>\n                        </table>\n                    </td>\n                </tr>\n            </table>\n            <table border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"100%\">\n                <tr>\n                    <td align=\"left\" valign=\"top\" width=\"100%\">\n                        <!--Body-->\n                        <table align=\"left\" class=\"W300\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"452\">\n                            <tr>\n                                <td align=\"left\" valign=\"top\" width=\"100%\" style=\"font-family:Helvetica, Arial, sans-serif;color:{{ theme.font_color_secondary }};font-size:{{ fields.body_font_size }};mso-line-height-rule:exactly;line-height:{{ fields.body_font_size }};font-weight:normal;padding-bottom:10px;\"><!--[if mso]><a class=\"incomments font-color\" href=\"%%=RedirectTo(@bannerLink)=%%\" alias=\"Vacoda Text Banner\" style=\"text-decoration:none;\"><strong style=\"color:{{ theme.font_color }};text-decoration:none;font-weight:normal;\"><![endif]--><span>{{ fields.body }}</span><span class=\"valid-date\">{{ fields.valid_thru }}</span><!--[if mso]></strong></a><![endif]--></td>\n                            </tr>\n                        </table>\n                        <!--[if gte mso 9]>\n                        </td>\n                        <td valign=\"top\">\n                        <![endif]-->\n                        <!--CTA-->\n                        <table align=\"left\" class=\"W300\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"128\">\n                            <tr>\n                                <td class=\"textLalign\" align=\"left\" valign=\"top\" width=\"100%\" style=\"font-family:Helvetica, Arial, sans-serif;color:{{ theme.cta_font_color }};font-size:13px;font-weight:normal;padding-bottom:10px;padding-top:10px;text-align:right;\"><!--[if mso]><a class=\"incomments cta-font-color\" href=\"%%=RedirectTo(@bannerLink)=%%\" alias=\"Vacoda Text Banner\" style=\"color:{{ theme.cta_font_color }};text-decoration:none;\"><strong style=\"color:{{ theme.cta_font_color }};text-decoration:none;font-weight:normal;\"><![endif]-->{{ fields.cta }}<!--[if mso]></strong></a><![endif]--></td>\n                            </tr>\n                        </table>\n                    </td>\n                </tr>\n            </table>\n        </td>\n        <td align=\"left\" valign=\"top\" width=\"10\"></td>\n    </tr>\n</template>\n',NULL,N